import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodouser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodouser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserJoin(props: {
  body: ITodoListTodouser.IVerifyJoin;
}): Promise<ITodoListTodouser.IAuthorized> {
  // Check for duplicate email
  const existing = await MyGlobal.prisma.todo_list_todousers.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);
  const now = toISOStringSafe(new Date());
  const userId = v4();

  // Create user
  const user = await MyGlobal.prisma.todo_list_todousers.create({
    data: {
      id: userId,
      email: props.body.email,
      password_hash: hashedPassword,
      created_at: now,
      updated_at: now,
    },
  });

  // Create session
  const sessionId = v4();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.todo_list_todouser_sessions.create({
    data: {
      id: sessionId,
      todo_list_todouser_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Generate tokens
  const token = {
    access: jwt.sign(
      {
        type: "todoUser",
        id: user.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "todoUser",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function postTodoListTodoUserTodos(props: {
  todoUser: TodouserPayload;
  body: ITodoListTodo.ICreate;
}): Promise<ITodoListTodo> {
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.todo_list_todos.create({
    data: {
      id: v4(),
      todo_list_todouser_id: props.todoUser.id,
      title: props.body.title,
      description: props.body.description ?? null,
      is_completed: false,
      created_at: now,
      updated_at: now,
      completed_at: null,
    },
  });
  return {
    id: created.id,
    todo_list_todouser_id: created.todo_list_todouser_id,
    title: created.title,
    description: created.description ?? undefined,
    is_completed: created.is_completed,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at:
      created.completed_at !== null
        ? toISOStringSafe(created.completed_at)
        : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function putTodoListTodoUserTodosTodoId(props: {
  todoUser: TodouserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  // Fetch the target todo by ID and verify ownership
  const todo = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: { id: props.todoId },
  });
  if (!todo) throw new HttpException("Todo item not found", 404);
  if (todo.todo_list_todouser_id !== props.todoUser.id) {
    throw new HttpException("Forbidden: You do not own this todo", 403);
  }

  // Prepare updates for allowed fields, setting updated_at to now
  const now = toISOStringSafe(new Date());

  // Determine title: if present in body, use it; else keep original
  const title = props.body.title !== undefined ? props.body.title : todo.title;
  // Determine description: if present (including null), use it; else keep existing
  const description =
    props.body.description !== undefined
      ? props.body.description
      : todo.description;

  // Determine is_completed state (defaults to existing if omitted)
  const isCompleted =
    props.body.is_completed !== undefined
      ? props.body.is_completed
      : todo.is_completed;

  // Determine completed_at field
  let completedAt: string | null | undefined = undefined;
  if (props.body.is_completed !== undefined) {
    if (props.body.is_completed === true) {
      completedAt =
        props.body.completed_at !== undefined
          ? (props.body.completed_at ?? now)
          : now;
    } else if (props.body.is_completed === false) {
      completedAt = null;
    }
  } else if (props.body.completed_at !== undefined) {
    completedAt = props.body.completed_at;
  } else {
    completedAt =
      todo.completed_at !== null && todo.completed_at !== undefined
        ? toISOStringSafe(todo.completed_at)
        : null;
  }

  // Execute update with only allowed fields
  const updated = await MyGlobal.prisma.todo_list_todos.update({
    where: { id: props.todoId },
    data: {
      title,
      description,
      is_completed: isCompleted,
      completed_at: completedAt ?? undefined,
      updated_at: now,
    },
  });

  // Return output per DTO contract (undefined for omitted optionals, null for explicit nullables)
  return {
    id: updated.id,
    todo_list_todouser_id: updated.todo_list_todouser_id,
    title: updated.title,
    description: updated.description ?? undefined,
    is_completed: updated.is_completed,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at:
      updated.completed_at !== null && updated.completed_at !== undefined
        ? toISOStringSafe(updated.completed_at)
        : (updated.completed_at ?? undefined),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { IPageITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function patchTodoListTodoUserTodos(props: {
  todoUser: TodouserPayload;
  body: ITodoListTodo.IRequest;
}): Promise<IPageITodoListTodo.ISummary> {
  const { todoUser, body } = props;
  const page = body.page ?? 1;
  const limitRaw = body.limit ?? 20;
  const limit = Math.min(Math.max(limitRaw, 1), 50);

  // Fix: Initialize as {} not undefined, and only spread actual objects
  let created_at: { gte?: string; lte?: string } = {};
  if (body.created_from !== undefined && body.created_from !== null) {
    created_at = { ...created_at, gte: body.created_from };
  }
  if (body.created_to !== undefined && body.created_to !== null) {
    created_at = { ...created_at, lte: body.created_to };
  }
  let updated_at: { gte?: string; lte?: string } = {};
  if (body.updated_from !== undefined && body.updated_from !== null) {
    updated_at = { ...updated_at, gte: body.updated_from };
  }
  if (body.updated_to !== undefined && body.updated_to !== null) {
    updated_at = { ...updated_at, lte: body.updated_to };
  }

  const where = {
    todo_list_todouser_id: todoUser.id,
    ...(body.is_completed !== undefined && { is_completed: body.is_completed }),
    ...(body.search && { title: { contains: body.search } }),
    ...(Object.keys(created_at).length > 0 && { created_at }),
    ...(Object.keys(updated_at).length > 0 && { updated_at }),
  };

  const allowedSortBy = ["created_at", "updated_at", "title"] as const;
  const sortField = allowedSortBy.includes(body.sort_by as any)
    ? (body.sort_by as "created_at" | "updated_at" | "title")
    : "created_at";
  const sortOrder: "asc" | "desc" =
    body.sort_order === "asc" || body.sort_order === "desc"
      ? body.sort_order
      : sortField === "title"
        ? "asc"
        : "desc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_list_todos.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip: (page - 1) * limit,
      take: limit,
      select: {
        id: true,
        title: true,
        is_completed: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.todo_list_todos.count({ where }),
  ]);
  const data = rows.map((row) => ({
    id: row.id,
    title: row.title,
    is_completed: row.is_completed,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));
  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodouser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodouser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserLogin(props: {
  body: ITodoListTodouser.IVerifyLogin;
}): Promise<ITodoListTodouser.IAuthorized> {
  const user = await MyGlobal.prisma.todo_list_todousers.findFirst({
    where: { email: props.body.email },
  });
  if (!user) {
    throw new HttpException("Invalid email or password", 401);
  }
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid email or password", 401);
  }
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const sessionId = v4();
  await MyGlobal.prisma.todo_list_todouser_sessions.create({
    data: {
      id: sessionId,
      todo_list_todouser_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });
  const token = {
    access: jwt.sign(
      {
        type: "todoUser",
        id: user.id,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "todoUser",
        id: user.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodouser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodouser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserRefresh(props: {
  body: ITodoListTodouser.IVerifyRefresh;
}): Promise<ITodoListTodouser.IAuthorized> {
  // 1. Decode and validate refresh token
  let decoded: { id: string; session_id: string; type: "todoUser" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "todoUser" };
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "todoUser") {
    throw new HttpException("Invalid token type", 401);
  }
  // 2. Find the session and ensure not expired
  const session = await MyGlobal.prisma.todo_list_todouser_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_list_todouser_id: decoded.id,
    },
    include: {
      todoListTodouser: true,
    },
  });
  const now = Date.now();
  if (!session) {
    throw new HttpException("Session not found or expired", 401);
  }
  if (session.expired_at && new Date(session.expired_at).getTime() <= now) {
    throw new HttpException("Session has expired", 401);
  }
  const user = session.todoListTodouser;
  if (!user) {
    throw new HttpException("User not found", 404);
  }
  // 3. Issue new tokens
  const accessExpireTime = 60 * 60 * 1000; // 1hr
  const refreshExpireTime = 7 * 24 * 60 * 60 * 1000; // 7d
  const issuedAt: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );
  const accessExpire = new Date(now + accessExpireTime);
  const refreshExpire = new Date(now + refreshExpireTime);
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "todoUser",
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: issuedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "todoUser",
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: issuedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpire),
    refreshable_until: toISOStringSafe(refreshExpire),
  };
  // 4. Update session.expired_at and user.updated_at
  await MyGlobal.prisma.todo_list_todouser_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: toISOStringSafe(refreshExpire) },
  });
  const updatedUser = await MyGlobal.prisma.todo_list_todousers.update({
    where: { id: decoded.id },
    data: { updated_at: issuedAt },
  });
  // 5. Compose response
  return {
    id: updatedUser.id,
    email: updatedUser.email,
    created_at: toISOStringSafe(updatedUser.created_at),
    updated_at: toISOStringSafe(updatedUser.updated_at),
    token,
  };
}

